<template>
  <div class="auth-diagram">
    <div class="ad-header">
      <span class="ad-tag">{{ t('diagram.tag') }}</span>
      <p class="ad-desc">{{ t('diagram.desc') }}</p>
    </div>

    <div class="canvas">
      <!-- IdP Node -->
      <div
        class="node idp-node"
        :class="{ active: selected === 'idp' }"
        @click="toggle('idp')"
        role="button"
        tabindex="0"
        @keydown.enter="toggle('idp')"
      >
        <div class="node-glow"></div>
        <div class="node-icon">🔐</div>
        <div class="node-name">{{ t('diagram.idp.name') }}</div>
        <div class="node-sub">{{ t('diagram.idp.sub') }}</div>
        <div class="node-hint">{{ t('diagram.clickHint') }} ↓</div>
      </div>

      <!-- Arrow: IdP → Portal (WebSocket) -->
      <div class="arrow-col single">
        <div class="arrow-label ws-lbl">WebSocket</div>
        <div class="arrow-track">
          <div class="flow-dot ws-dot"></div>
        </div>
        <div class="arrow-tip green-tip">▶</div>
      </div>

      <!-- Portal Node -->
      <div
        class="node portal-node"
        :class="{ active: selected === 'portal' }"
        @click="toggle('portal')"
        role="button"
        tabindex="0"
        @keydown.enter="toggle('portal')"
      >
        <div class="node-glow"></div>
        <div class="hub-badge">{{ t('diagram.portal.badge') }}</div>
        <div class="node-icon">⚡</div>
        <div class="node-name">{{ t('diagram.portal.name') }}</div>
        <div class="node-sub">{{ t('diagram.portal.sub') }}</div>
      </div>

      <!-- Arrow: Portal ↔ Solutions (JWT + Heartbeat) -->
      <div class="arrow-col double">
        <div class="arrow-row">
          <div class="arrow-label jwt-lbl">JWT</div>
          <div class="arrow-track">
            <div class="flow-dot jwt-dot"></div>
          </div>
          <div class="arrow-tip green-tip">▶</div>
        </div>
        <div class="arrow-row reverse">
          <div class="arrow-tip amber-tip">◀</div>
          <div class="arrow-track">
            <div class="flow-dot hb-dot"></div>
          </div>
          <div class="arrow-label hb-lbl">Heartbeat</div>
        </div>
      </div>

      <!-- Solutions Group -->
      <div
        class="solutions-group"
        :class="{ active: selected === 'solutions' }"
        @click="toggle('solutions')"
        role="button"
        tabindex="0"
        @keydown.enter="toggle('solutions')"
      >
        <div class="node-glow sol-glow"></div>
        <div class="sol-node">
          <span class="sol-icon">◈</span>
          <span>{{ t('diagram.solutions.a') }}</span>
        </div>
        <div class="sol-node">
          <span class="sol-icon">◈</span>
          <span>{{ t('diagram.solutions.b') }}</span>
        </div>
        <div class="sol-node sol-ext">
          <span class="sol-icon">+</span>
          <span>{{ t('diagram.solutions.n') }}</span>
        </div>
        <div class="node-hint center-hint">{{ t('diagram.clickHint') }} ↓</div>
      </div>
    </div>

    <!-- Detail Panel -->
    <div class="detail-panel" :class="{ open: selected !== null }">
      <div class="panel-inner">
        <button class="panel-close" @click="selected = null" aria-label="close">✕</button>

        <!-- IdP Panel -->
        <template v-if="selected === 'idp'">
          <h4 class="panel-title blue-title">{{ t('diagram.idp.panelTitle') }}</h4>
          <p class="panel-body">{{ t('diagram.idp.body') }}</p>
          <div class="panel-section">
            <span class="section-label why-label">{{ t('diagram.whyLabel') }}</span>
            <p class="section-text">{{ t('diagram.idp.why') }}</p>
          </div>
          <div class="panel-section">
            <span class="section-label improved-label">{{ t('diagram.improvedLabel') }}</span>
            <ul class="panel-list">
              <li v-for="(item, i) in tm('diagram.idp.improved')" :key="i">{{ item }}</li>
            </ul>
          </div>
          <pre class="code-block"><code v-html="idpCode"></code></pre>
        </template>

        <!-- Portal Panel -->
        <template v-else-if="selected === 'portal'">
          <h4 class="panel-title green-title">{{ t('diagram.portal.panelTitle') }}</h4>
          <p class="panel-body">{{ t('diagram.portal.body') }}</p>
          <div class="panel-section">
            <span class="section-label why-label">{{ t('diagram.whyLabel') }}</span>
            <p class="section-text">{{ t('diagram.portal.why') }}</p>
          </div>
          <div class="panel-section">
            <span class="section-label improved-label">{{ t('diagram.improvedLabel') }}</span>
            <ul class="panel-list">
              <li v-for="(item, i) in tm('diagram.portal.improved')" :key="i">{{ item }}</li>
            </ul>
          </div>
          <pre class="code-block"><code v-html="portalCode"></code></pre>
        </template>

        <!-- Solutions Panel -->
        <template v-else-if="selected === 'solutions'">
          <h4 class="panel-title purple-title">{{ t('diagram.solutions.panelTitle') }}</h4>
          <p class="panel-body">{{ t('diagram.solutions.body') }}</p>
          <div class="panel-section">
            <span class="section-label why-label">{{ t('diagram.whyLabel') }}</span>
            <p class="section-text">{{ t('diagram.solutions.why') }}</p>
          </div>
          <div class="panel-section">
            <span class="section-label improved-label">{{ t('diagram.improvedLabel') }}</span>
            <ul class="panel-list">
              <li v-for="(item, i) in tm('diagram.solutions.improved')" :key="i">{{ item }}</li>
            </ul>
          </div>
          <pre class="code-block"><code v-html="solutionsCode"></code></pre>
        </template>
      </div>
    </div>
  </div>
</template>

<script setup>
import { ref } from 'vue'
import { useI18n } from 'vue-i18n'

const { t, tm } = useI18n()
const selected = ref(null)

function toggle(id) {
  selected.value = selected.value === id ? null : id
}

// ── Java 21 코드 스니펫 (HTML 엔티티 이스케이프 처리) ──────────────────

const idpCode = `<span class="cm">// WebSocket 메시지 수신 후 사용자 식별자 파싱</span>
<span class="ck">public record</span> <span class="cf">UserIdentity</span>(
    String userPk, String department, List&lt;String&gt; roles) {}

<span class="ca">@Component</span>
<span class="ck">public class</span> <span class="cf">WebSocketAuthHandler</span> <span class="ck">extends</span> TextWebSocketHandler {

    <span class="ca">@Override</span>
    <span class="ck">protected void</span> <span class="cf">handleTextMessage</span>(
            WebSocketSession session, TextMessage message) {

        <span class="ck">var</span> payload  = objectMapper.readValue(message.getPayload(), Map.<span class="ck">class</span>);
        <span class="ck">var</span> identity = <span class="ck">new</span> UserIdentity(
            (String)       payload.get(<span class="cs">"employeeId"</span>),
            (String)       payload.get(<span class="cs">"dept"</span>),
            (List&lt;String&gt;) payload.get(<span class="cs">"roles"</span>)
        );
        tokenService.issue(identity, session);
    }
}`

const portalCode = `<span class="ck">public sealed interface</span> <span class="cf">SolutionToken</span>
    <span class="ck">permits</span> SolutionToken.Active, SolutionToken.Expired {}

<span class="ck">public record</span> <span class="cf">Active</span>(String jwt, Instant expiresAt)  <span class="ck">implements</span> SolutionToken {}
<span class="ck">public record</span> <span class="cf">Expired</span>(String reason)               <span class="ck">implements</span> SolutionToken {}

<span class="ca">@Service</span>
<span class="ck">public class</span> <span class="cf">TokenIssueService</span> {

    <span class="ck">public</span> SolutionToken <span class="cf">issue</span>(UserIdentity identity, SolutionConfig solution) {
        <span class="ck">var</span> claims = Map.of(
            <span class="cs">"sub"</span>,         identity.userPk(),
            <span class="cs">"roles"</span>,       identity.roles(),
            <span class="cs">"solutionId"</span>,  solution.id(),
            <span class="cs">"permissions"</span>, solution.resolvePermissions(identity.roles())
        );
        <span class="ck">var</span> jwt = Jwts.builder()
            .claims(claims)
            .issuedAt(Date.from(Instant.now()))
            .expiration(Date.from(Instant.now().plus(solution.tokenTtl())))
            .signWith(solution.signature())   <span class="cm">// 솔루션 고유 Signature</span>
            .compact();

        <span class="ck">return new</span> Active(jwt, Instant.now().plus(solution.tokenTtl()));
    }
}

<span class="cm">// Polling Heartbeat — 세션 활성 여부 관리</span>
<span class="ca">@Scheduled</span>(fixedDelay = <span class="cn">30_000</span>)
<span class="ck">public void</span> <span class="cf">cleanupExpiredSessions</span>() {
    sessionStore.findAll()
        .stream()
        .filter(s -> s.isExpired() || !heartbeatStore.isAlive(s.sessionId()))
        .forEach(sessionStore::invalidate);
}`

const solutionsCode = `<span class="cm">// 솔루션 측 최소 구현 — JWT 검증 필터</span>
<span class="ck">public class</span> <span class="cf">JwtAuthFilter</span> <span class="ck">extends</span> OncePerRequestFilter {

    <span class="ca">@Override</span>
    <span class="ck">protected void</span> <span class="cf">doFilterInternal</span>(
            HttpServletRequest req, HttpServletResponse res, FilterChain chain)
            <span class="ck">throws</span> ServletException, IOException {

        <span class="ck">var</span> token = resolveToken(req);

        <span class="ck">switch</span> (token) {
            <span class="ck">case</span> <span class="ck">null</span> -> {
                res.sendError(HttpServletResponse.SC_UNAUTHORIZED, <span class="cs">"Token required"</span>);
                <span class="ck">return</span>;
            }
            <span class="ck">default</span> -> {
                <span class="ck">var</span> claims = Jwts.parser()
                    .verifyWith(solutionSignature)   <span class="cm">// 포털이 발급한 Signature</span>
                    .build()
                    .parseSignedClaims(token)
                    .getPayload();

                <span class="ck">var</span> auth = <span class="ck">new</span> JwtAuthToken(
                    claims.getSubject(),
                    (List&lt;String&gt;) claims.get(<span class="cs">"permissions"</span>)
                );
                SecurityContextHolder.getContext().setAuthentication(auth);
                chain.doFilter(req, res);
            }
        }
    }
}

<span class="cm">// 신규 솔루션 등록 — Signature 등록만으로 완료</span>
<span class="ck">public record</span> <span class="cf">SolutionRegistration</span>(
    String solutionId, SecretKey signature, Duration tokenTtl) {}

<span class="ca">@PostMapping</span>(<span class="cs">"/admin/solutions/register"</span>)
<span class="ck">public</span> ResponseEntity&lt;Void&gt; <span class="cf">register</span>(<span class="ca">@RequestBody</span> SolutionRegistration reg) {
    signatureRegistry.register(reg);  <span class="cm">// 이후 동일한 플로우 자동 적용</span>
    <span class="ck">return</span> ResponseEntity.ok().build();
}`
</script>

<style scoped>
.auth-diagram {
  margin: 48px 0 56px;
  padding: 32px 36px;
  background: var(--bg2);
  border: 1px solid var(--br);
  border-radius: 12px;
  position: relative;
  overflow: hidden;
}
.auth-diagram::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(ellipse 60% 40% at 50% 0%, rgba(0,255,136,0.04) 0%, transparent 70%);
  pointer-events: none;
}

/* Header */
.ad-header { margin-bottom: 32px; }
.ad-tag {
  display: inline-block;
  font-size: 10px;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--g);
  background: rgba(0,255,136,0.08);
  border: 1px solid rgba(0,255,136,0.25);
  padding: 4px 12px;
  border-radius: 2px;
  margin-bottom: 10px;
}
.ad-desc {
  font-size: 12px;
  color: var(--tm);
  letter-spacing: 0.02em;
}

/* Canvas */
.canvas {
  display: flex;
  align-items: center;
  gap: 0;
  overflow-x: auto;
  padding-bottom: 4px;
}

/* Nodes */
.node {
  flex-shrink: 0;
  width: 154px;
  padding: 22px 18px 18px;
  border-radius: 10px;
  background: var(--bg3);
  cursor: pointer;
  transition: transform 0.3s, box-shadow 0.3s, border-color 0.3s;
  text-align: center;
  position: relative;
  user-select: none;
}
.node-glow {
  position: absolute;
  inset: 0;
  border-radius: 10px;
  opacity: 0;
  transition: opacity 0.3s;
  pointer-events: none;
}
.node:hover { transform: translateY(-5px); }
.node:hover .node-glow,
.node.active .node-glow { opacity: 1; }

.node-icon { font-size: 24px; margin-bottom: 10px; }
.node-name {
  font-size: 12px;
  font-weight: 700;
  color: var(--tb);
  margin-bottom: 4px;
  line-height: 1.4;
}
.node-sub {
  font-size: 10px;
  color: var(--tm);
  letter-spacing: 0.04em;
  line-height: 1.5;
}
.node-hint {
  font-size: 9px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  margin-top: 10px;
  opacity: 0;
  transition: opacity 0.2s;
}
.node:hover .node-hint,
.node.active .node-hint { opacity: 1; }

/* IdP */
.idp-node { border: 1px solid var(--b); }
.idp-node .node-glow { background: radial-gradient(ellipse at 50% 100%, rgba(56,189,248,0.15), transparent 70%); }
.idp-node .node-name { color: var(--b); }
.idp-node .node-hint { color: var(--b); }
.idp-node:hover, .idp-node.active { box-shadow: 0 8px 32px rgba(56,189,248,0.2); border-color: rgba(56,189,248,0.7); }

/* Portal */
.portal-node { border: 2px solid var(--g); width: 154px; }
.portal-node .node-glow { background: radial-gradient(ellipse at 50% 100%, rgba(0,255,136,0.18), transparent 70%); }
.portal-node .node-name { color: var(--g); }
.portal-node:hover, .portal-node.active { box-shadow: 0 8px 36px rgba(0,255,136,0.28); border-color: #7fffc4; }
.hub-badge {
  position: absolute;
  top: -11px; left: 50%;
  transform: translateX(-50%);
  font-size: 9px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  background: var(--g);
  color: #000;
  padding: 2px 10px;
  border-radius: 10px;
  font-weight: 700;
  white-space: nowrap;
}

/* Solutions Group */
.solutions-group {
  flex-shrink: 0;
  display: flex;
  flex-direction: column;
  gap: 7px;
  cursor: pointer;
  position: relative;
  padding: 4px;
  border-radius: 10px;
  border: 1px solid transparent;
  transition: border-color 0.3s;
  user-select: none;
}
.sol-glow {
  position: absolute;
  inset: 0;
  border-radius: 10px;
  background: radial-gradient(ellipse at 50% 50%, rgba(167,139,250,0.1), transparent 70%);
  opacity: 0;
  transition: opacity 0.3s;
  pointer-events: none;
}
.solutions-group:hover { border-color: rgba(167,139,250,0.3); }
.solutions-group:hover .sol-glow,
.solutions-group.active .sol-glow { opacity: 1; }
.solutions-group.active { border-color: rgba(167,139,250,0.5); box-shadow: 0 8px 32px rgba(167,139,250,0.15); }

.sol-node {
  padding: 0 16px;
  height: 42px;
  background: var(--bg3);
  border: 1px solid var(--p);
  border-radius: 7px;
  font-size: 11px;
  color: var(--p);
  display: flex;
  align-items: center;
  gap: 8px;
  transition: transform 0.3s, box-shadow 0.3s;
  width: 150px;
  box-sizing: border-box;
}
.solutions-group:hover .sol-node,
.solutions-group.active .sol-node { transform: translateX(3px); box-shadow: 0 0 12px rgba(167,139,250,0.2); }
.sol-icon { font-size: 12px; opacity: 0.7; flex-shrink: 0; }
.sol-ext { border-style: dashed; }
.center-hint {
  font-size: 9px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: var(--p);
  text-align: center;
  opacity: 0;
  transition: opacity 0.2s;
  margin-top: 2px;
}
.solutions-group:hover .center-hint,
.solutions-group.active .center-hint { opacity: 1; }

/* Arrows */
.arrow-col {
  flex: 1;
  min-width: 72px;
  display: flex;
  flex-direction: column;
  align-items: stretch;
  justify-content: center;
  padding: 0 6px;
  gap: 10px;
}
.arrow-col.single { align-items: center; flex-direction: row; gap: 0; }

/* Single arrow (IdP→Portal) */
.arrow-col.single .arrow-label { margin-right: 4px; }
.arrow-col.single .arrow-track { flex: 1; }

.arrow-row {
  display: flex;
  align-items: center;
  gap: 0;
  width: 100%;
}
.arrow-row.reverse { flex-direction: row; }

.arrow-track {
  flex: 1;
  height: 2px;
  background: rgba(255,255,255,0.06);
  border-radius: 1px;
  position: relative;
  overflow: hidden;
}
.flow-dot {
  position: absolute;
  top: 0; left: 0;
  width: 45%;
  height: 100%;
  border-radius: 1px;
}

/* Flow animations */
.ws-dot  { background: linear-gradient(90deg, transparent, var(--b), transparent); animation: flowR 2s linear infinite; }
.jwt-dot { background: linear-gradient(90deg, transparent, var(--g), transparent); animation: flowR 1.8s linear infinite; }
.hb-dot  { background: linear-gradient(90deg, transparent, var(--p), transparent); animation: flowL 2.2s linear infinite; }

@keyframes flowR {
  0%   { transform: translateX(-120%); }
  100% { transform: translateX(280%); }
}
@keyframes flowL {
  0%   { transform: translateX(280%); }
  100% { transform: translateX(-120%); }
}

.arrow-label {
  font-size: 9px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  white-space: nowrap;
  flex-shrink: 0;
  padding: 0 4px;
}
.ws-lbl  { color: var(--b); }
.jwt-lbl { color: var(--g); margin-right: 4px; }
.hb-lbl  { color: var(--p); margin-left: 4px; }

.arrow-tip { font-size: 10px; flex-shrink: 0; }
.green-tip  { color: var(--g); }
.amber-tip  { color: var(--p); }

/* Detail Panel */
.detail-panel {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.5s cubic-bezier(0.4, 0, 0.2, 1);
}
.detail-panel.open { max-height: 1600px; }

.panel-inner {
  margin-top: 28px;
  padding: 24px 28px;
  background: var(--bg3);
  border: 1px solid var(--br);
  border-radius: 8px;
  position: relative;
}

/* Panel body & sections */
.panel-body {
  font-size: 13px;
  color: var(--t);
  line-height: 1.8;
  margin-bottom: 18px;
}
.panel-section {
  margin-bottom: 16px;
}
.section-label {
  display: inline-block;
  font-size: 9px;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  font-weight: 700;
  padding: 3px 10px;
  border-radius: 2px;
  margin-bottom: 8px;
}
.why-label      { background: rgba(56,189,248,0.1);  color: var(--b); border: 1px solid rgba(56,189,248,0.25); }
.improved-label { background: rgba(0,255,136,0.08);  color: var(--g); border: 1px solid rgba(0,255,136,0.2); }
.section-text {
  font-size: 12.5px;
  color: var(--t);
  line-height: 1.8;
}
.panel-close {
  position: absolute;
  top: 14px; right: 16px;
  background: transparent;
  border: 1px solid var(--br);
  color: var(--tm);
  font-size: 11px;
  width: 26px; height: 26px;
  border-radius: 4px;
  cursor: pointer;
  display: flex; align-items: center; justify-content: center;
  transition: all 0.2s;
}
.panel-close:hover { border-color: var(--g); color: var(--g); }

.panel-title {
  font-family: var(--mono);
  font-size: 13px;
  font-weight: 700;
  margin-bottom: 14px;
  letter-spacing: 0.02em;
}
.blue-title   { color: var(--b); }
.green-title  { color: var(--g); }
.purple-title { color: var(--p); }

.panel-list {
  list-style: none;
  padding: 0;
  margin: 0 0 18px;
  display: flex;
  flex-direction: column;
  gap: 7px;
}
.panel-list li {
  font-size: 12px;
  color: var(--t);
  line-height: 1.7;
  padding-left: 14px;
  position: relative;
}
.panel-list li::before {
  content: '›';
  position: absolute;
  left: 0;
  color: var(--g);
  font-weight: 700;
}

/* Code block */
.code-block {
  background: var(--bg);
  border: 1px solid var(--br);
  border-left: 2px solid var(--g);
  border-radius: 6px;
  padding: 16px 20px;
  font-family: var(--mono);
  font-size: 11.5px;
  line-height: 1.75;
  overflow-x: auto;
  margin: 0;
  color: var(--t);
}
.code-block code { font-family: inherit; }
.cm { color: var(--tm); font-style: italic; }
.ck { color: var(--b); }
.cf { color: var(--g); }
.cs { color: var(--a); }
.cn { color: var(--p); }
.ca { color: #f97316; }

@media (max-width: 900px) {
  .auth-diagram { padding: 24px 20px; }
  .canvas { gap: 0; }
  .node { width: 130px; padding: 18px 14px 14px; }
  .portal-node { width: 130px; }
  .sol-node { width: 128px; font-size: 10px; height: 38px; }
  .arrow-col { min-width: 52px; }
}
</style>
