<template>
  <div class="portfolio-root">
    <!-- Noise grain overlay -->
    <svg id="noise" xmlns="http://www.w3.org/2000/svg">
      <filter id="n">
        <feTurbulence type="fractalNoise" baseFrequency="0.75" numOctaves="4" stitchTiles="stitch"/>
      </filter>
      <rect width="100%" height="100%" filter="url(#n)"/>
    </svg>

    <!-- Scroll progress bar -->
    <div id="progress"></div>

    <canvas id="bg-canvas"></canvas>
    <div id="cursor"></div>
    <div id="cursor-ring"></div>

    <NavBar />
    <HeroSection />
    <CoreCompetency />
    <DecisionLog />
    <ExperienceSection />
    <SkillsSection />
    <ProjectsSection />
    <ContactSection />
    <ChatBot />
  </div>
</template>

<script setup>
import { onMounted } from 'vue'
import NavBar from './components/NavBar.vue'
import HeroSection from './components/HeroSection.vue'
import CoreCompetency from './components/CoreCompetency.vue'
import DecisionLog from './components/DecisionLog.vue'
import ExperienceSection from './components/ExperienceSection.vue'
import SkillsSection from './components/SkillsSection.vue'
import ProjectsSection from './components/ProjectsSection.vue'
import ContactSection from './components/ContactSection.vue'
import ChatBot from './components/ChatBot.vue'

onMounted(() => {
  /* ── Scroll Progress Bar ── */
  const progressEl = document.getElementById('progress')
  window.addEventListener('scroll', () => {
    const h = document.documentElement.scrollHeight - window.innerHeight
    if (h > 0) progressEl.style.width = (window.scrollY / h * 100) + '%'
  })

  /* ── Constellation Canvas ── */
  const canvas = document.getElementById('bg-canvas')
  const ctx = canvas.getContext('2d')
  let W, H, pts = []

  function resize() {
    W = canvas.width = window.innerWidth
    H = canvas.height = window.innerHeight
  }
  resize()
  window.addEventListener('resize', () => { resize(); initPts() })

  function initPts() {
    pts = []
    const n = Math.floor(W * H / 12000)
    for (let i = 0; i < n; i++) {
      pts.push({
        x: Math.random() * W,
        y: Math.random() * H,
        vx: (Math.random() - 0.5) * 0.25,
        vy: (Math.random() - 0.5) * 0.25,
        r: Math.random() * 1.2 + 0.3,
        o: Math.random() * 0.4 + 0.15,
        phase: Math.random() * Math.PI * 2
      })
    }
  }
  initPts()

  let frame = 0
  function draw() {
    ctx.clearRect(0, 0, W, H)
    frame++
    pts.forEach(p => {
      p.x += p.vx; p.y += p.vy
      if (p.x < 0) p.x = W; if (p.x > W) p.x = 0
      if (p.y < 0) p.y = H; if (p.y > H) p.y = 0
      const o = p.o * (0.5 + 0.5 * Math.sin(frame * 0.015 + p.phase))
      ctx.beginPath()
      ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2)
      ctx.fillStyle = `rgba(0,255,136,${o})`
      ctx.fill()
    })
    for (let i = 0; i < pts.length; i++) {
      for (let j = i + 1; j < pts.length; j++) {
        const dx = pts[i].x - pts[j].x
        const dy = pts[i].y - pts[j].y
        const d = Math.sqrt(dx * dx + dy * dy)
        if (d < 140) {
          ctx.beginPath()
          ctx.moveTo(pts[i].x, pts[i].y)
          ctx.lineTo(pts[j].x, pts[j].y)
          ctx.strokeStyle = `rgba(0,255,136,${(1 - d / 140) * 0.22})`
          ctx.lineWidth = 0.7
          ctx.stroke()
        }
      }
    }
    requestAnimationFrame(draw)
  }
  draw()

  /* Mouse attract particles (clusters near cursor → lines become visible) */
  let mx = 0, my = 0
  document.addEventListener('mousemove', e => {
    mx = e.clientX; my = e.clientY
    pts.forEach(p => {
      const dx = mx - p.x, dy = my - p.y
      const d = Math.sqrt(dx * dx + dy * dy)
      if (d < 150) {
        p.vx += (dx / d) * 0.008
        p.vy += (dy / d) * 0.008
      }
    })
  })

  /* ── Custom Cursor ── */
  const cur = document.getElementById('cursor')
  const ring = document.getElementById('cursor-ring')
  let rx = 0, ry = 0

  document.addEventListener('mousemove', e => {
    cur.style.left = e.clientX + 'px'
    cur.style.top = e.clientY + 'px'
  })

  function animRing() {
    rx += (mx - rx) * 0.1
    ry += (my - ry) * 0.1
    ring.style.left = rx + 'px'
    ring.style.top = ry + 'px'
    requestAnimationFrame(animRing)
  }
  animRing()

  const hoverSel = 'a, button, .d-card, .stat-card, .comp-col, .sg, .chip, .proj-card, .etag, .lang-btn'
  document.querySelectorAll(hoverSel).forEach(el => {
    el.addEventListener('mouseenter', () => {
      cur.style.width = '18px'; cur.style.height = '18px'
      ring.style.width = '56px'; ring.style.height = '56px'
      ring.style.borderColor = 'rgba(0,255,136,0.55)'
    })
    el.addEventListener('mouseleave', () => {
      cur.style.width = '10px'; cur.style.height = '10px'
      ring.style.width = '38px'; ring.style.height = '38px'
      ring.style.borderColor = 'rgba(0,255,136,0.35)'
    })
  })

  /* Magnetic buttons */
  document.querySelectorAll('.btn').forEach(btn => {
    btn.addEventListener('mousemove', e => {
      const r = btn.getBoundingClientRect()
      const x = (e.clientX - r.left - r.width / 2) * 0.3
      const y = (e.clientY - r.top - r.height / 2) * 0.3
      btn.style.transform = `translate(${x}px,${y}px)`
    })
    btn.addEventListener('mouseleave', () => { btn.style.transform = '' })
  })
})
</script>

<style>
@import url('https://fonts.googleapis.com/css2?family=JetBrains+Mono:ital,wght@0,300;0,400;0,500;0,700;1,400&family=Syne:wght@400;700;800&display=swap');

*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

:root {
  --g: #00ff88; --gd: #00cc6a;
  --g10: rgba(0,255,136,0.1); --g20: rgba(0,255,136,0.2);
  --a: #ffb347; --b: #38bdf8; --p: #a78bfa; --r: #f472b6;
  --bg: #030608; --bg2: #060c12; --bg3: #0a1220; --bg4: #0d1828;
  --br: rgba(0,255,136,0.12); --br2: rgba(0,255,136,0.28); --br3: rgba(0,255,136,0.5);
  --t: #b0bec5; --tb: #ecf0f1; --tm: #546e7a;
  --mono: 'JetBrains Mono', monospace;
  --disp: 'Syne', sans-serif;
}

html { scroll-behavior: smooth; }

body {
  background: var(--bg);
  color: var(--t);
  font-family: var(--mono);
  font-size: 14px;
  line-height: 1.7;
  overflow-x: hidden;
  cursor: none;
}

/* Vignette */
body::before {
  content: '';
  position: fixed;
  inset: 0;
  background: radial-gradient(ellipse at center, transparent 35%, rgba(0,0,0,0.75) 100%);
  pointer-events: none;
  z-index: 1;
}

/* Scanlines */
body::after {
  content: '';
  position: fixed;
  inset: 0;
  background: repeating-linear-gradient(
    0deg, transparent, transparent 3px,
    rgba(0,0,0,0.05) 3px, rgba(0,0,0,0.05) 4px
  );
  pointer-events: none;
  z-index: 1;
}

/* Noise */
#noise {
  position: fixed;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  opacity: 0.03;
}

/* Scroll progress */
#progress {
  position: fixed;
  top: 0; left: 0;
  height: 2px;
  background: linear-gradient(90deg, var(--g), var(--b), var(--p));
  z-index: 999;
