<template>
  <nav class="navbar">
    <a href="#" class="logo">서상훈<em>.dev</em></a>
    <div class="nav-links">
      <a href="#competency" :class="{ active: activeSection === 'competency' }">{{ t('nav.competency') }}</a>
      <a href="#decisions"  :class="{ active: activeSection === 'decisions'  }">{{ t('nav.decisions') }}</a>
      <a href="#experience" :class="{ active: activeSection === 'experience' }">{{ t('nav.experience') }}</a>
      <a href="#skills"     :class="{ active: activeSection === 'skills'     }">{{ t('nav.skills') }}</a>
      <a href="#contact"    :class="{ active: activeSection === 'contact'    }">{{ t('nav.contact') }}</a>
    </div>
    <div class="nav-right">
      <div class="nav-status">
        <div class="pulse-dot"></div>
        Seoul, KR · Available
      </div>
      <div class="nav-lang">
        <button
          v-for="loc in locales"
          :key="loc.code"
          :class="['lang-btn', { active: locale === loc.code }]"
          @click="setLocale(loc.code)"
        >
          {{ loc.label }}
        </button>
      </div>
    </div>
  </nav>
</template>

<script setup>
import { ref, onMounted, onBeforeUnmount } from 'vue'
import { useI18n } from 'vue-i18n'

const { t, locale } = useI18n()

const locales = [
  { code: 'ko', label: 'KO' },
  { code: 'en', label: 'EN' },
]

function setLocale(code) {
  locale.value = code
}

const activeSection = ref('')
// 문서 순서대로 정의 (hero가 최상단)
const ORDERED_IDS = ['hero', 'competency', 'decisions', 'experience', 'skills', 'contact']

let observer = null
const intersecting = new Set()

function updateActive() {
  // 현재 intersecting 중인 섹션 중 문서 순서상 가장 위 것을 선택
  for (const id of ORDERED_IDS) {
    if (intersecting.has(id)) {
      activeSection.value = id === 'hero' ? '' : id
      return
    }
  }
  activeSection.value = ''
}

onMounted(() => {
  observer = new IntersectionObserver(entries => {
    entries.forEach(entry => {
      if (entry.isIntersecting) {
        intersecting.add(entry.target.id)
      } else {
        intersecting.delete(entry.target.id)
      }
    })
    updateActive()
  }, { threshold: 0.3 })

  ORDERED_IDS.forEach(id => {
    const el = document.getElementById(id)
    if (el) observer.observe(el)
  })
})

onBeforeUnmount(() => {
  observer?.disconnect()
})
</script>

<style scoped>
.navbar {
  position: fixed;
  top: 0; left: 0; right: 0;
  z-index: 200;
  padding: 14px 48px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: rgba(5, 8, 13, 0.9);
  backdrop-filter: blur(20px);
  border-bottom: 1px solid var(--br);
}

.logo {
  font-family: var(--disp);
  font-weight: 800;
  font-size: 17px;
  color: var(--g);
  letter-spacing: -0.5px;
  text-decoration: none;
}
.logo em { color: var(--t); font-style: normal; }

.nav-links {
  display: flex;
  gap: 28px;
}
.nav-links a {
  color: var(--tm);
  text-decoration: none;
  font-size: 11px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  transition: color 0.2s;
  position: relative;
}
.nav-links a::after {
  content: '';
  position: absolute;
  bottom: -4px; left: 0;
  width: 0; height: 1px;
  background: var(--g);
  transition: width 0.3s;
}
.nav-links a:hover { color: var(--g); }
.nav-links a:hover::after { width: 100%; }
.nav-links a.active { color: var(--g); }
.nav-links a.active::after {
  width: 100%;
  box-shadow: 0 0 6px var(--g);
}

.nav-right {
  display: flex;
  align-items: center;
  gap: 16px;
}

.nav-status {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 11px;
  color: var(--tm);
}

.pulse-dot {
  width: 7px; height: 7px;
  background: var(--g);
  border-radius: 50%;
  animation: pulse 2s infinite;
}
@keyframes pulse {
  0%, 100% { box-shadow: 0 0 0 0 rgba(0,255,136,0.4); }
  50% { box-shadow: 0 0 0 6px rgba(0,255,136,0); }
}

.nav-lang { display: flex; gap: 6px; }
.lang-btn {
  font-family: var(--mono);
  font-size: 10px;
  letter-spacing: 0.12em;
  padding: 3px 8px;
  background: transparent;
  border: 1px solid var(--br);
  border-radius: 2px;
  color: var(--tm);
  cursor: pointer;
  transition: all 0.2s;
}
.lang-btn:hover,
.lang-btn.active {
  border-color: var(--g);
  color: var(--g);
}

@media (max-width: 720px) {
  .navbar { padding: 12px 16px; }
  .nav-links { display: none; }
  .nav-status { display: none; }
}
</style>
